    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_1LC1RA_0RB0LC_1LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_1LC1RA_0RB0LC_1LA0RC = Some t ->
