(** 1RB1RD_1LC1RA_0RB0LC_1LD0RB *)
(** 1RB1RD_1LC1RA_0RB0LC_1LD0RB -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1RD_1LC1RA_0RB0LC_1LD0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DR StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S1 DL StD | StD, S1 => mk S0 DR StB end.

(** Its mirror 1LB1LD_1RC1LA_0LB0RC_1RD0LB: the same counter grown leftward.  Every
